      SUBROUTINE DBENDICC     CALCULATES PARTIAL DERIVATIVES OF THE FIRST-ORDERC     TRANSFER MATRIX OF A BENDING MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM28.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'WMN.CIN'CC     LOCAL VARIABLESC      REAL  KVKH, KVKVCC--------------------------------------------------------------      IL = IPTOJ(NL)      IB = IPTOJ(NBV)      IRHO = IPTOJ(NRHO)      IANG = IPTOJ(NANG)      IK1 = IPTOJ(NK1)      RH = 1.0 + RMPS      IF (JV .EQ. NL) GO TO 10      IF (JV .EQ. NBV) GO TO 20      IF (JV .EQ. NRHO) GO TO 30      IF (JV .EQ. NANG) GO TO 40      IF (JV .EQ. NN) GO TO 50      IF (JV .EQ. NK1) GO TO 60      IF (JV .EQ. NRMPS) GO TO 140      IF (JV .EQ. NRNMS) GO TO 150      IF (JV .EQ. NVR) GO TO 160      IF (JV .EQ. NNP) GO TO 170      IF (JV .EQ. NK1P) GO TO 170      IF (JV .EQ. NTILT) GO TO 180      GO TO 500CC     MAGNET LENGTH IS VARIEDC   10 LV = DPARM*UNITI(8)      LVE = LV      IF (IB .NE. 0 .OR. IRHO .NE. 0) THEN        IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          LVE = LVE/CSA2        ENDIF        GO TO 100      ELSE IF (IANG .NE. 0) THEN        IF (TYPE .EQ. 28) LVE = LVE*LBEND/LRBEND        IF (IK1 .EQ. 0) THEN          GO TO 110        ELSE          KVKH = - H0**2*LVE/LBEND          KVKV = 0.0          HV = - H0*LVE/LBEND          GO TO 130        ENDIF      ENDIF      RETURNCC     MAGNETIC FIELD IS VARIEDC   20 IF (IL .NE. 0 .AND. IK1 .EQ. 0) THEN        KVK = DPARM*B*UNITI(9)/(RI*PREF)        KVKH = KVK*WMN        KVKV = KVK*RH*NB        HV = DPARM*UNITI(9)/PREF        IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          LVE = ( - L + LRBEND/CSA2)*UNITI(9)/B        ENDIF        GO TO 120      ELSE IF (IL .NE. 0 .AND. IK1 .NE. 0) THEN        KVKH = DPARM*B*UNITI(9)/(RI*PREF)        KVKV = 0.0        HV = DPARM*UNITI(9)/PREF        IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          LVE = (- L + LRBEND/CSA2)*UNITI(9)/B        ENDIF        GO TO 120      ELSE IF (IANG .NE. 0 .AND. IK1 .EQ. 0) THEN        LVE = - DPARM*UNITI(9)*RI**2*AL/(B**2*PREF)        GO TO 110      ELSE IF (IANG .NE. 0 .AND. IK1 .NE. 0) THEN        LVE = - DPARM*L*UNITI(9)/B        KVKH = H0*UNITI(9)/PREF        KVKV = 0.0        HV = UNITI(9)/PREF        GO TO 130      ENDIF      GO TO 500CC     RADIUS OF CURVATURE OF REFERENCE ORBIT IS VARIEDC   30 IF (IL .NE. 0 .AND. IK1 .EQ. 0) THEN        KVK = - DPARM*H0**3*UNITI(8)        KVKH = KVK*WMN        KVKV = KVK*RH*NB        HV = - H0**2*UNITI(8)        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        LVE = (AL - H0*LRBEND/CSA2)*UNITI(8)        GO TO 120      ELSE IF (IL .NE. 0 .AND. IK1 .NE. 0) THEN        KVKH = - DPARM*H0**3*UNITI(8)        KVKV = 0.0        HV = - H0**2*UNITI(8)        IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          LVE = (AL - H0*LRBEND/CSA2)*UNITI(8)        ENDIF        GO TO 120      ELSE IF (IANG .NE. 0 .AND. IK1 .EQ. 0) THEN        LVE = DPARM*AL*UNITI(8)        GO TO 110      ELSE IF (IANG .NE. 0 .AND. IK1 .NE. 0) THEN        LVE = DPARM*AL*UNITI(8)        KVKH = - H0**3*UNITI(8)        KVKV = 0.0        HV = - H0**2*UNITI(8)        GO TO 130      ENDIF      GO TO 500CC     BEND ANGLE IS VARIEDC   40 IF (IL .NE. 0 .AND. IK1 .EQ. 0) THEN        KVK = DPARM*H0*UNITI(7)/LBEND        KVKH = KVK*WMN        KVKV = KVK*RH*NB        HV = UNITI(7)/LBEND        IF (AL .NE. 0.0) THEN          LVE = 0.5*LRBEND*(1.0 - 0.5*AL/TAN(0.5*AL))/SIN(0.5*AL)     1          *UNITI(7)        ELSE          LVE = 0.0        ENDIF        GO TO 120      ELSE IF (IL .NE. 0 .AND. IK1 .NE. 0) THEN        IF (TYPE .EQ. 4 .OR. TYPE .EQ. 29) THEN          KVKH = DPARM*H0*UNITI(7)/L          KVKV = 0.0          HV = UNITI(7)/LBEND          GO TO 120        ELSE          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          KVKH = 2.0*SNA2*CSA2*UNITI(7)/LRBEND**2          KVKV = 0.0          HV = CSA2*UNITI(7)/LRBEND          RHO = 0.0          IF (H0 .NE. 0.0) RHO = 1.0/H0          LVE = RHO*(1.0 - L*CSA2/LRBEND)*UNITI(7)          GO TO 130        ENDIF      ELSE IF (IB .NE. 0 .OR. IRHO .NE. 0) THEN        RHO = 0.0        IF (H0 .NE. 0.0) RHO = 1.0/H0        LVE = DPARM*RHO*UNITI(7)        GO TO 100      ENDIF      RETURNCC     DIMENSIONLESS FIELD INDEX N IS VARIEDC   50 KVKH = - 0.5*DPARM*H0**2      KVKV = 0.5*DPARM*H0**2*RH      HV = 0.0      LVE = 0.0      GO TO 120CC     FIELD INDEX K1 IS VARIEDC   60 KVKH = 0.5*DPARM*UNITI(8)**2      KVKV = - 0.5*DPARM*UNITI(8)**2      HV = 0.0      LVE = 0.0      GO TO 120CC     LENGTH CHANGES BUT FIELD STAYS CONSTANTC  100 LINEAR = .FALSE.      JQUAD = 1      KQ2 = KX2      CALL DFOL      JQUAD = 3      KQ2 = KY2      CALL DFOL      RV(1,6) = H0*SX*LVE      RV(5,2) = - RV(1,6)      RV(2,6) = H0*CX*LVE      RV(5,1) = - RV(2,6)      RV(5,6) = (CX - 1.0)*LVE/WMN      GO TO 500CC     LENGTH CHANGES BUT BEND ANGLE STAYS CONSTANTC  110 RV(1,2) = SX*LVE/L      RV(2,1) = KX2*SX*LVE/L      RV(3,4) = SY*LVE/L      RV(4,3) = KY2*SY*LVE/L      RV(1,6) = DISP*LVE/L      RV(5,2) = - DISP*LVE/L      RV(5,6) = R56*LVE/L      GO TO 500CC     MAGNETIC FIELD OR FIELD INDEX IS VARIED BUT LENGTH STAYS CONSTANTC  120 LINEAR = .FALSE.      JQUAD = 1      H = H0*(1.0 + RMPS)      KQ2 = KX2      KVK = KVKH      CALL DFOCUS      JQUAD = 3      KQ2 = KY2      KVK = KVKV      CALL DFOCUS      IF (TYPE .EQ. 28) THEN        RV(1,1) = RV(1,1) - KX2*SX*LVE        RV(1,2) = RV(1,2) + CX*LVE        RV(2,1) = RV(2,1) - KX2*CX*LVE        RV(2,2) = RV(2,2) - KX2*SX*LVE        RV(3,3) = RV(3,3) - KY2*SY*LVE        RV(3,4) = RV(3,4) + CY*LVE        RV(4,3) = RV(4,3) - KY2*CY*LVE        RV(4,4) = RV(4,4) - KY2*SY*LVE      ENDIF      IF (KX2 .NE. 0.0) RV(1,6) = (- 2.0*DISP + H0*L*SX)*KVKH/KX2     1    + HV*DISP/H0      IF (TYPE .EQ. 28) RV(1,6) = RV(1,6) + H0*SX*LVE      RV(5,2) = - RV(1,6)      IF (TYPE .EQ. 28) RV(2,6) = RV(2,6) + H0*CX*LVE      IF (KX2 .NE. 0.0) RV(2,6) = H*RV(1,2) + HV*DDISP/H0      RV(5,1) = - RV(2,6)      IF (KX2 .NE. 0.0)     1    RV(5,6) = (- 3.0*R56 - H0*L*DISP)*KVKH/KX2 + 2.0*R56*HV/H0      GO TO 500CC     LENGTH IS VARIED BUT FIELD AND K1 STAY CONSTANTC  130 LINEAR = .FALSE.      RV(1,1) = - (KX2*LVE + L*KVKH)*SX      RV(1,2) = LVE*CX + (L*CX - SX)*KVKH/KX2      RV(2,1) = - KX2*LVE*CX - (SX + L*CX)*KVKH      RV(2,2) = RV(1,1)      RV(3,3) = K1*LVE*SY      RV(3,4) = CY*LVE      RV(4,3) = K1*LVE*CY      RV(4,4) = RV(3,3)      RV(1,6) = (HV/KX2 - 2.0*H0*KVKH/KX2**2)*(1.0 - CX)     1        + H0*SX*LBEND*KVKH/KX2 + H0*SX*LVE      RV(5,2) = - RV(1,6)      RV(2,6) =  HV*SX + H0*RV(1,2)      RV(5,1) = - RV(2,6)      RV(5,6) = (AL**2*RV(1,2) +     1          ( - AL**2 + 2.0*K1*L*R56)*LVE)/(AL**2 - K1*L**2)      GO TO 500CC     EXCESS FIELD FRACTION RMPS IS VARIEDC  140 LINEAR = .FALSE.      HEX = RMPS*H0      H = H0 + HEX      DHEX = DPARM*H0      DCOV = .TRUE.      CODV(1) = - DPARM*DISP      CODV(2) = - DPARM*DDISP      SKX = KX2*SX      SKY = KY2*SY      DCXX = - H0*DHEX*(2.0 - NB)      DCYY = - H0*DHEX*NB      RV(1,1) = 0.5*DCXX*L*SX      RV(1,2) = 0.5*DCXX*SMLCX/KX2      RV(2,1) = 0.5*DCXX*(SX + L*CX)      RV(2,2) = 0.5*DCXX*L*SX      RV(1,6) = DHEX*DISN     1        + H*DCXX*(1.0 - CX - 0.5*L*SKX)/KX2**2      RV(2,6) = DHEX*SX     1        + 0.5*H*DCXX*(SKX - KX2*L*CX)/KX2**2      RV(3,3) = 0.5*DCYY*L*SY      IF (KY2 .NE. 0.0) RV(3,4) = 0.5*DCYY*(SY - L*CY)/KY2      RV(4,3) = 0.5*DCYY*(SY + L*CY)      RV(4,4) = 0.5*DCYY*L*SY      GO TO 500CC     SKEW FIELD MULTIPLIER RNMS IS VARIEDC  150 HEX = RMPS*H0      V = VRN*H0      IF (V .NE. 0.0) DCOV = .TRUE.      DV = DPARM*V      H = H0 + HEX      CODV(3) = DPARM*V*SY**2/(1.0 + CY)      CODV(4) = DPARM*V*SY      SKX = KX2*SX      SKY = KY2*SY      DCXY = H0*(V - H0*NPN)      DCYX = H0*(2.0*V - H0*NPN)      RV(1,3) = DCXY*(CY - CX)/(KX2 - KY2)      RV(1,4) = DCXY*(SY - SX)/(KX2 - KY2)      RV(2,3) = DCXY*(SKX - SKY)/(KX2 - KY2)      RV(2,4) = DCXY*(CY - CX)/(KX2 - KY2)      RV(3,1) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,2) = DCYX*(SX - SY)/(KY2 - KX2)      RV(4,1) = DCYX*(SKY - SKX)/(KY2 - KX2)      RV(4,2) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,6) = - DV*SY**2/(1.0 + CY)     1        + H*DCYX*(DSVN + (CX - CY)/(KX2 - KY2))/KX2      RV(4,6) = - DV*SY     1        + H*DCYX*(SY - (SKX - SKY)/(KX2 - KY2))/KX2      GO TO 500CC     NORMALIZED SKEW DIPOLE FIELD IS VARIEDC  160 DCOV = .TRUE.      HEX = RMPS*H0      H = H0 + HEX      SKX = KX2*SX      SKY = KY2*SY      DV = DPARM*H0      CODV(3) = DPARM*RNMS*H0*SY**2/(1.0 + CY)      CODV(4) = DPARM*RNMS*H0*SY      DCXY = DPARM*H0*RNMS*DV      DCYX = 2.0*DPARM*H*RNMS*DV      RV(1,3) = DCXY*(CX - CY)/(KY2 - KX2)      RV(1,4) = DCXY*(SX - SY)/(KY2 - KX2)      RV(2,3) = DCXY*(SKX - SKY)/(KX2 - KY2)      RV(2,4) = DCXY*(CX - CY)/(KY2 - KX2)      RV(3,1) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,2) = DCYX*(SX - SY)/(KY2 - KX2)      RV(4,1) = DCYX*(SKX - SKY)/(KX2 - KY2)      RV(4,2) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,6) = - DV*RNMS*SY**2/(1.0 + CY)     1        + H*DCYX*(DSVN + (CX - CY)/(KX2 - KY2))/KX2      RV(4,6) = - DV*RNMS*SY     1        + H*DCYX*(SY - (SKX - SKY)/(KX2 - KY2))/KX2      GO TO 500CC     NORMALIZED SKEW QUADRUPOLE FIELD IS VARIEDC  170 HEX = RMPS*H0      H = H0 + HEX      SKX = KX2*SX      SKY = KY2*SY      DCXY = - DPARM*H0**2*RNMS      DCYX = - DPARM*H0**2*RNMS      IF (JV .EQ. NK1P) THEN        DCXY = DCXY/(UNITI(8)*H0)**2        DCYX = DCYX/(UNITI(8)*H0)**2      ENDIF      RV(1,3) = DCXY*(CY - CX)/(KX2 - KY2)      RV(1,4) = DCXY*(SY - SX)/(KX2 - KY2)      RV(2,3) = DCXY*(SKX - SKY)/(KX2 - KY2)      RV(2,4) = DCXY*(CY - CX)/(KX2 - KY2)      RV(3,1) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,2) = DCYX*(SX - SY)/(KY2 - KX2)      RV(4,1) = DCYX*(SKX - SKY)/(KX2 - KY2)      RV(4,2) = DCYX*(CX - CY)/(KY2 - KX2)      RV(3,6) = H*DCYX*(DSVN + (CX - CY)/(KX2 - KY2))/KX2      RV(4,6) = H*DCYX*(SY - (SKX - SKY)/(KX2 - KY2))/KX2      GO TO 500CC     TILT IS VARIEDC  180 IF (JV .EQ. NTILT .AND. REFER) THEN        CALL DSROTR      ENDIFCC     RETURNC  500 RETURN      END